for($i=1;$i<=2;$i++){Quote::create(['uuid'=>Str::uuid(),'company_id'=>$company->id,'customer_id'=>1,'quote_number'=>'DV-2026-00'.$i,'total'=>120]);Invoice::create(['uuid'=>Str::uuid(),'company_id'=>$company->id,'customer_id'=>1,'invoice_number'=>'FA-2026-00'.$i,'total'=>120]);}
}}
